sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_style;
uniform float amzp_tile;
uniform float amzp_speedM;
uniform float amzp_lineS;
uniform float amzp_varA;
uniform float amzp_opac;
uniform float amzp_styleCols;
layout(color) uniform half4 amzp_colA;
layout(color) uniform half4 amzp_colB;
uniform float amzp_showBg;
layout(color) uniform half4 amzp_bgCol;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    const float NMCUT = 0.04;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float nmZ() { return max(amzp_scale * 2.0, 0.002); }
    float2 nmStd(float2 p, float pxsc) {
        p -= amzp_position * pxsc;
        p = nmRot(p, -radians(amzp_angle));
        return p / (nmZ() * max(amzp_stretch, float2(0.01)));
    }
    float2 stdFC() {
        float2 W = layer;
        float2 q = amzLayerNorm() * W - 0.5 * W;
        q.y = -q.y;
        q = nmStd(q, pxs());
        q.y = -q.y;
        return q + 0.5 * W;
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 fr = clamp(fx * amzp_hardness, 0.0, 64.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) {
            float na = clamp((f.a - NMCUT) / (1.0 - NMCUT), 0.0, 1.0);
            o = float4(f.rgb * (na / max(f.a, 0.0001)), na);
        }
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + fr.rgb, max(b.a, max(f.a, max(f.r, max(f.g, f.b)))));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float4 stRings(float2 I, float2 W, float T, float3 cA, float3 cB) {
        float2 b = (I - W * 0.5) / W.y;
        float R = max(0.5 * amzp_tile, 0.01);
        float2 c = mod(b + 0.5 * R, R) - 0.5 * R;
        float l = length(c);
        float t = 0.075 * T;
        float aa = 1.0 / (W.y * nmZ());
        float period = max(0.08 * amzp_lineS, 0.002);
        float th = (0.35 * amzp_varA - l) * 0.1;
        float inb = smoothstep(-aa, aa, th - mod(l - t, period)) * step(l, R) * smoothstep(0.0, aa, th);
        float red = smoothstep(-aa, aa, th - mod(l - t, period * 2.0));
        float3 rc = red > 0.5 ? cB : cA;
        return float4(rc * inb, inb);
    }
    float Sk(float2 U) { U = sqrt(abs(fract(U) - 0.5)); U += U.yx; return U.x * U.x; }
    float kaw(float2 u, float2 R, float T) {
        float2 U = (u - R / 2.0) / max(R.x, R.y);
        float2 V = U / max(0.1 * amzp_tile, 0.001);
        float d = R.x > R.y ? U.x : U.y;
        return min(Sk(V), Sk(V - 0.5)) - (0.648 * amzp_lineS - 0.48 * amzp_varA * d) * abs(cos(0.628 * T - d));
    }
    float4 stKawung(float2 I, float2 W, float T, float3 cA) {
        float s = kaw(I, W, T);
        float e = 1.0 / nmZ();
        float fw = (abs(kaw(I + float2(e, 0.0), W, T) - s) + abs(kaw(I + float2(0.0, e), W, T) - s));
        float v = 1.0 - clamp(0.5 + s / max(fw, 1e-5), 0.0, 1.0);
        return float4(cA * v, v);
    }
    float box(float2 st, float2 amzLocal_size, float sm) {
        amzLocal_size = float2(0.5) - amzLocal_size * 0.5;
        float2 aa = float2(sm * 0.5);
        float2 uv = smoothstep(amzLocal_size, amzLocal_size + aa, st) * smoothstep(amzLocal_size, amzLocal_size + aa, float2(1.0) - st);
        return uv.x * uv.y;
    }
    float4 stTartan(float2 I, float2 W, float T, float3 cG, float3 cP) {
        float2x2 spin = rot2(-3.14159265 + sin(T / 20.0) * amzp_varA);
        float tsc = (1.0 + sin(T / 10.0) / 30.0 * amzp_varA) / max(amzp_tile, 0.01);
        float2 st = I / W;
        st.x *= W.x / W.y;
        float2 stD = st;
        st = st - 0.5;
        st = st * spin;
        st = fract((st + 0.5) * tsc);
        float2 sG = fract(st * 2.0 + float2(0.5));
        float gV = box(sG - float2(0.092, 0.0), float2(1.0 / 6.0, 2.0), 0.0) + box(sG + float2(0.092, 0.0), float2(1.0 / 6.0, 2.0), 0.0);
        float gH = box(sG - float2(0.0, 0.092), float2(2.0, 1.0 / 6.0), 0.0) + box(sG + float2(0.0, 0.092), float2(2.0, 1.0 / 6.0), 0.0);
        float2 sP = fract(st);
        float pV = box(sP - float2(0.25, 0.0), float2(0.1, 2.0), 0.0) + box(sP - float2(0.3125, 0.0), float2(1.0 / 128.0, 2.0), 0.0)
                 + box(sP - float2(0.329, 0.0), float2(1.0 / 128.0, 2.0), 0.0) + box(sP - float2(0.1875, 0.0), float2(1.0 / 128.0, 2.0), 0.0)
                 + box(sP - float2(0.171, 0.0), float2(1.0 / 128.0, 2.0), 0.0) + box(sP + float2(0.2975, 0.0), float2(1.0 / 16.0, 2.0), 0.0)
                 + box(sP + float2(0.2025, 0.0), float2(1.0 / 16.0, 2.0), 0.0) + box(sP + float2(0.25, 0.0), float2(1.0 / 64.0, 2.0), 0.0);
        float pH = box(sP + float2(0.0, 0.25), float2(2.0, 0.1), 0.0) + box(sP + float2(0.0, 0.3125), float2(2.0, 1.0 / 128.0), 0.0)
                 + box(sP + float2(0.0, 0.329), float2(2.0, 1.0 / 128.0), 0.0) + box(sP + float2(0.0, 0.1875), float2(2.0, 1.0 / 128.0), 0.0)
                 + box(sP + float2(0.0, 0.171), float2(2.0, 1.0 / 128.0), 0.0) + box(sP - float2(0.0, 0.2975), float2(2.0, 1.0 / 16.0), 0.0)
                 + box(sP - float2(0.0, 0.2025), float2(2.0, 1.0 / 16.0), 0.0) + box(sP - float2(0.0, 0.25), float2(2.0, 1.0 / 64.0), 0.0);
        float3 cV = cG * gV + cP * pV;
        float3 cH = cG * gH + cP * pH;
        float covV = clamp(gV + pV, 0.0, 1.0), covH = clamp(gH + pH, 0.0, 1.0);
        stD = stD - 0.5;
        stD = stD * rot2(-3.14159265 / 4.0) * spin;
        stD = fract((stD + 0.5) * (96.0 / max(amzp_lineS, 0.05)));
        float dg = box(stD, float2(2.0, 0.75), 0.5);
        return float4(min(mix(cV, cH, dg), float3(1.0)), mix(covV, covH, dg));
    }
    float4 stSquare(float2 I, float2 W, float T, float3 cA, float3 cB) {
        float grid = 10.0 / max(amzp_tile, 0.05);
        float aspect = W.y / W.x;
        float2 uv = I / W.x;
        uv -= float2(0.5, 0.5 * aspect);
        float a = radians(45.0);
        uv = float2x2(cos(a), -sin(a), sin(a), cos(a)) * uv;
        uv += float2(0.5, 0.5 * aspect);
        uv.y += 0.5 * (1.0 - aspect);
        float2 amzLocal_pos = grid * uv;
        float2 rep = fract(amzLocal_pos);
        float dist = 2.0 * min(min(rep.x, 1.0 - rep.x), min(rep.y, 1.0 - rep.y));
        float sq = length((floor(amzLocal_pos) + float2(0.5)) - float2(grid * 0.5));
        float edge = (T - sq * 0.5 * amzp_lineS) * 0.5;
        edge = 2.0 * fract(edge * 0.5);
        float value = fract(dist * 2.0);
        value = mix(value, 1.0 - value, step(1.0, edge));
        edge = pow(abs(1.0 - edge), 2.0);
        float sf = 0.05 * max(amzp_varA, 0.01);
        value = smoothstep(edge - sf, edge, 0.95 * value);
        value += sq * 0.1 * 10.0 / max(grid, 0.1);
        float3 c = mix(cA, cB, clamp(value, 0.0, 1.0));
        float al = clamp(0.25 * clamp(value, 0.0, 1.0), 0.0, 1.0);
        return float4(c * al, al);
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 I = stdFC();
        float T = TT() * amzp_speedM;
        float3 cA, cB, cBg;
        if ((amzp_styleCols>0.5)) {
            if (int(amzp_style) == 0) { cA = float3(1.0); cB = float3(1.0, 0.0, 0.0); cBg = float3(0.0); }
            else if (int(amzp_style) == 1) { cA = float3(0.0); cB = float3(0.0); cBg = float3(1.0); }
            else if (int(amzp_style) == 2) { cA = float3(0.016, 0.345, 0.220); cB = float3(0.173, 0.173, 0.506); cBg = float3(0.0); }
            else { cA = float3(1.0); cB = float3(0.5, 0.75, 1.0); cBg = float3(0.0); }
        } else {
            cA = amzp_colA.rgb; cB = amzp_colB.rgb; cBg = amzp_bgCol.rgb;
        }
        float4 P;
        if (int(amzp_style) == 0) P = stRings(I, W, T, cA, cB);
        else if (int(amzp_style) == 1) P = stKawung(I, W, T, cA);
        else if (int(amzp_style) == 2) P = stTartan(I, W, T, cA, cB);
        else P = stSquare(I, W, T, cA, cB);
        P *= clamp(amzp_opac, 0.0, 4.0);
        float4 G = P;
        if ((amzp_showBg>0.5)) G = float4(P.rgb + cBg * (1.0 - P.a), 1.0);
        amzOutput = nmBlend(orig, nmGradMap(G));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
